static xd3_sec_stream *xd3_lzma_alloc(xd3_stream *stream) {
  return (xd3_sec_stream *)xd3_alloc(stream, sizeof(xd3_lzma_stream), 1);
}

static void xd3_lzma_destroy(xd3_stream *stream, xd3_sec_stream *sec_stream) {
